custom_css:
.sc-tw :root{
            color-scheme: dark;
            --night: oklch(15% 0.04 220);
            --tealwood: oklch(24% 0.05 220);
            --sunset: oklch(64% 0.16 54);
            --amber: oklch(76% 0.15 75);
            --indigo: oklch(23% 0.08 275);
            --ink: oklch(96% 0.01 220);
            --muted: rgba(255, 255, 255, .68);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            font-family: "Inter Tight", sans-serif;
            background:
                radial-gradient(circle at 50% 0%, rgba(255, 154, 90, .26), transparent 24%),
                radial-gradient(circle at 20% 14%, rgba(61, 145, 142, .16), transparent 20%),
                linear-gradient(180deg, oklch(18% 0.05 28) 0%, oklch(15% 0.04 220) 42%, oklch(13% 0.04 240) 100%);
            color: white;
        }.sc-tw body::before{
            content: "";
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image:
                linear-gradient(rgba(255, 255, 255, .03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255, 255, 255, .03) 1px, transparent 1px);
            background-size: 104px 104px;
            opacity: .18;
            mask-image: radial-gradient(circle at center, black 35%, transparent 88%);
            z-index: -2;
        }.sc-tw .display{
            font-family: "Cormorant Garamond", serif;
            letter-spacing: -.06em;
        }.sc-tw .mono{
            font-family: "IBM Plex Mono", monospace;
        }.sc-tw .cozy-layer{
            background:
                linear-gradient(180deg, rgba(20, 36, 38, .88), rgba(12, 21, 24, .78)),
                linear-gradient(135deg, rgba(255, 185, 102, .08), transparent 38%);
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .06),
                0 26px 80px rgba(0, 0, 0, .34);
            backdrop-filter: blur(24px) saturate(1.08);
            -webkit-backdrop-filter: blur(24px) saturate(1.08);
        }.sc-tw .lantern-core{
            position: relative;
            overflow: hidden;
            border-radius: 999px;
            background: linear-gradient(180deg, rgba(20, 22, 24, .94), rgba(11, 13, 16, .9));
            border: 1px solid rgba(255, 255, 255, .12);
            color: white;
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), box-shadow .45s ease, border-color .35s ease;
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .06),
                0 18px 60px rgba(0, 0, 0, .28);
        }.sc-tw .lantern-core::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 50% 50%, rgba(255, 189, 98, .14), transparent 36%),
                radial-gradient(circle at 50% 50%, rgba(255, 145, 62, .08), transparent 54%);
            opacity: 0;
            transition: .45s ease;
            pointer-events: none;
        }.sc-tw .lantern-core::after{
            content: "";
            position: absolute;
            inset: -120%;
            background:
                linear-gradient(120deg, transparent 44%, rgba(255, 193, 103, .52) 50%, transparent 56%);
            transform: translateX(-140%) rotate(10deg);
            animation: sheen 9s ease-in-out infinite;
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .lantern-core:hover{
            transform: translateY(-3px);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .06),
                0 0 0 1px rgba(255, 189, 98, .18),
                0 22px 60px rgba(0, 0, 0, .34);
        }.sc-tw .lantern-core:hover::before{
            opacity: 1;
        }.sc-tw .hero{
            min-height: 100svh;
            position: relative;
            overflow: hidden;
            background: linear-gradient(180deg, rgba(255, 153, 84, .3) 0%, rgba(18, 21, 28, .86) 52%, rgba(11, 14, 18, .95) 100%);
        }.sc-tw .hero-video{
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            will-change: transform;
            mask-image: radial-gradient(circle at center, black 0 52%, rgba(0, 0, 0, .92) 64%, rgba(0, 0, 0, .62) 78%, transparent 94%);
            -webkit-mask-image: radial-gradient(circle at center, black 0 52%, rgba(0, 0, 0, .92) 64%, rgba(0, 0, 0, .62) 78%, transparent 94%);
        }.sc-tw .hero::after{
            content: "";
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at center, rgba(255, 189, 98, .14), transparent 18%),
                radial-gradient(circle at center, rgba(0, 0, 0, .15), rgba(0, 0, 0, .22) 55%, rgba(0, 0, 0, .38) 100%);
            pointer-events: none;
        }.sc-tw .hero-center{
            position: relative;
            z-index: 5;
            min-height: 100svh;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 110px 24px 42px;
        }.sc-tw .hero-shell{
            max-width: 980px;
            padding: 28px 30px 30px;
            border-radius: 2.2rem;
        }.sc-tw .hero-kicker{
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 12px 16px;
            border-radius: 999px;
            background: rgba(255, 255, 255, .08);
            border: 1px solid rgba(255, 255, 255, .12);
            color: rgba(255, 255, 255, .8);
            text-transform: uppercase;
            letter-spacing: .3em;
            font-size: 10px;
        }.sc-tw .hero-kicker span{
            width: 8px;
            height: 8px;
            background: var(--amber);
            display: inline-block;
            box-shadow: 0 0 18px rgba(255, 193, 103, .55);
        }.sc-tw .hero-title{
            margin-top: 24px;
            font-size: clamp(4.4rem, 10vw, 9.2rem);
            line-height: .82;
            letter-spacing: -.09em;
            color: white;
            text-shadow: 0 18px 38px rgba(0, 0, 0, .22);
            animation: breath 7s ease-in-out infinite;
        }.sc-tw .hero-sub{
            margin: 26px auto 0;
            max-width: 760px;
            font-size: 18px;
            line-height: 1.95;
            color: rgba(255, 255, 255, .84);
        }.sc-tw .hero-actions{
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 14px;
            margin-top: 34px;
        }.sc-tw .hero-actions button{
            height: 56px;
            padding: 0 22px;
            border: none;
            cursor: pointer;
            font-size: 10px;
            letter-spacing: .26em;
            text-transform: uppercase;
        }.sc-tw .hero-chips{
            display: flex;
            flex-wrap: wrap;
            justify-content: center;
            gap: 10px;
            margin-top: 24px;
        }.sc-tw .hero-chips span{
            padding: 10px 12px;
            border-radius: 999px;
            background: rgba(255, 255, 255, .09);
            border: 1px solid rgba(255, 255, 255, .09);
            color: rgba(255, 255, 255, .9);
            text-transform: uppercase;
            letter-spacing: .2em;
            font-size: 10px;
        }.sc-tw .section{
            padding: 124px 0;
        }.sc-tw .wrap{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
        }.sc-tw .section-heading{
            display: flex;
            justify-content: space-between;
            gap: 22px;
            align-items: flex-end;
            margin-bottom: 30px;
        }.sc-tw .section-heading h2{
            font-size: clamp(3rem, 6vw, 6.2rem);
            line-height: .9;
            letter-spacing: -.07em;
        }.sc-tw .section-heading p{
            max-width: 470px;
            color: rgba(255, 255, 255, .7);
            line-height: 1.9;
        }.sc-tw .code-window{
            position: relative;
            width: min(1080px, calc(100% - 32px));
            margin: 0 auto;
            border-radius: 2.6rem;
            overflow: hidden;
            background:
                linear-gradient(180deg, rgba(22, 38, 40, .9), rgba(10, 16, 18, .92));
            border: 1px solid rgba(255, 255, 255, .08);
            box-shadow:
                0 26px 80px rgba(0, 0, 0, .38);
        }.sc-tw .code-top{
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            padding: 18px 20px;
            border-bottom: 1px solid rgba(255, 255, 255, .08);
            background: rgba(255, 255, 255, .03);
        }.sc-tw .dots{
            display: flex;
            gap: 8px;
        }.sc-tw .dots span{
            width: 10px;
            height: 10px;
            border-radius: 999px;
            background: rgba(255, 255, 255, .16);
        }.sc-tw .code-top .tag{
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .62);
        }.sc-tw .code-body{
            padding: 34px 22px 28px;
            display: grid;
            grid-template-columns: 1fr .72fr;
            gap: 28px;
        }.sc-tw .manifesto{
            min-height: 320px;
            padding: 24px;
            border-radius: 2rem;
            background: rgba(255, 255, 255, .04);
            border: 1px solid rgba(255, 255, 255, .08);
            position: relative;
            overflow: hidden;
        }.sc-tw .manifesto::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .04), transparent 24%),
                repeating-linear-gradient(180deg, rgba(255, 255, 255, .04) 0 1px, transparent 1px 28px);
            opacity: .24;
            pointer-events: none;
        }.sc-tw .manifesto .cursor{
            display: inline-block;
            width: 1px;
            height: 1.2em;
            background: rgba(255, 205, 127, .95);
            margin-left: 2px;
            animation: blink 1s steps(2, end) infinite;
            vertical-align: -3px;
        }.sc-tw .manifesto pre{
            margin: 0;
            white-space: pre-wrap;
            word-break: break-word;
            font-family: "IBM Plex Mono", monospace;
            font-size: 12px;
            line-height: 1.9;
            color: rgba(255, 255, 255, .8);
        }.sc-tw .manifesto .headline{
            margin-bottom: 16px;
            text-transform: uppercase;
            letter-spacing: .28em;
            color: rgba(255, 255, 255, .58);
            font-size: 10px;
        }.sc-tw .metrics{
            display: flex;
            flex-direction: column;
            gap: 16px;
        }.sc-tw .metric{
            padding: 20px;
            border-radius: 1.8rem;
            background: rgba(255, 255, 255, .05);
            border: 1px solid rgba(255, 255, 255, .08);
        }.sc-tw .metric .label{
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .58);
        }.sc-tw .metric .value{
            margin-top: 10px;
            font-size: clamp(2rem, 4vw, 3.4rem);
            line-height: 1;
            letter-spacing: -.06em;
            color: white;
        }.sc-tw .metric .sub{
            margin-top: 10px;
            font-size: 14px;
            line-height: 1.8;
            color: rgba(255, 255, 255, .72);
        }.sc-tw .projects{
            padding: 124px 0;
            background:
                radial-gradient(circle at 10% 0%, rgba(255, 179, 109, .12), transparent 16%),
                linear-gradient(180deg, rgba(26, 35, 42, .92), rgba(11, 14, 18, 1));
        }.sc-tw .projects-grid{
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            gap: 16px;
        }.sc-tw .project{
            grid-column: span 4;
            min-height: 240px;
            position: relative;
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, .08);
            border-radius: 2rem;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .02));
            opacity: 0;
            transform: translateY(20px);
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), opacity .45s ease, box-shadow .45s ease, border-color .45s ease;
            box-shadow: 0 18px 50px rgba(0, 0, 0, .24);
        }.sc-tw .project.reveal{
            opacity: 1;
            transform: translateY(0);
        }.sc-tw .project::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), transparent 32%),
                radial-gradient(circle at 70% 28%, rgba(255, 197, 113, .12), transparent 18%);
            pointer-events: none;
        }.sc-tw .project .inner{
            position: relative;
            z-index: 2;
            height: 100%;
            padding: 22px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }.sc-tw .project .label{
            text-transform: uppercase;
            letter-spacing: .28em;
            font-size: 10px;
            color: rgba(255, 255, 255, .62);
        }.sc-tw .project h3{
            font-size: clamp(1.8rem, 3vw, 3rem);
            line-height: .95;
            letter-spacing: -.05em;
            color: white;
        }.sc-tw .project p{
            margin-top: 12px;
            color: rgba(255, 255, 255, .72);
            line-height: 1.9;
            max-width: 36ch;
        }.sc-tw .project .on-hover{
            opacity: 0;
            transform: translateY(8px);
            transition: .35s ease;
            font-family: "IBM Plex Mono", monospace;
            text-transform: uppercase;
            letter-spacing: .2em;
            font-size: 10px;
            color: rgba(255, 205, 127, .92);
        }.sc-tw .project:hover{
            transform: translateY(-3px);
            border-color: rgba(255, 205, 127, .18);
            box-shadow: 0 22px 56px rgba(0, 0, 0, .3);
        }.sc-tw .project:hover .on-hover{
            opacity: 1;
            transform: translateY(0);
        }.sc-tw .project.wide{
            grid-column: span 8;
        }.sc-tw .project.tall{
            min-height: 320px;
        }.sc-tw .project .glow{
            position: absolute;
            inset: auto -20% -20% auto;
            width: 240px;
            height: 240px;
            background: radial-gradient(circle, rgba(255, 164, 72, .18), transparent 68%);
            filter: blur(20px);
            pointer-events: none;
            opacity: .8;
        }.sc-tw .footer{
            padding: 120px 0 94px;
            background:
                radial-gradient(circle at 20% 12%, rgba(255, 171, 89, .1), transparent 16%),
                linear-gradient(180deg, rgba(7, 10, 14, 1), rgba(11, 13, 16, 1));
        }.sc-tw .footer-shell{
            width: min(1600px, calc(100% - 32px));
            margin: 0 auto;
            padding: 36px;
            border: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .03), rgba(255, 255, 255, .015));
            box-shadow: 0 24px 80px rgba(0, 0, 0, .34);
            position: relative;
            overflow: hidden;
        }.sc-tw .roofline{
            position: absolute;
            inset: auto 0 0 0;
            height: 120px;
            background:
                linear-gradient(180deg, transparent 0%, rgba(255, 255, 255, .04) 100%),
                linear-gradient(90deg, transparent 0 8%, rgba(255, 255, 255, .08) 8% 8.6%, transparent 8.6% 15%, rgba(255, 255, 255, .08) 15% 15.4%, transparent 15.4% 24%, rgba(255, 255, 255, .08) 24% 24.6%, transparent 24.6% 100%);
            clip-path: polygon(0 100%, 6% 72%, 14% 80%, 20% 54%, 28% 70%, 35% 46%, 42% 58%, 50% 38%, 60% 64%, 70% 44%, 79% 62%, 88% 50%, 96% 70%, 100% 100%);
            opacity: .52;
            pointer-events: none;
        }.sc-tw .footer-grid{
            display: grid;
            grid-template-columns: 1.15fr .85fr;
            gap: 34px;
            align-items: end;
            position: relative;
            z-index: 2;
        }.sc-tw .footer-grid h2{
            font-size: clamp(3rem, 6vw, 6.2rem);
            line-height: .9;
            letter-spacing: -.07em;
            color: white;
        }.sc-tw .footer-grid p{
            margin-top: 16px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.95;
            max-width: 760px;
        }.sc-tw .links{
            display: flex;
            flex-wrap: wrap;
            gap: 14px;
            justify-content: flex-end;
        }.sc-tw .links a{
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 12px 14px;
            border-radius: 999px;
            background: rgba(255, 255, 255, .05);
            border: 1px solid rgba(255, 255, 255, .08);
            text-transform: uppercase;
            letter-spacing: .22em;
            font-size: 10px;
            color: rgba(255, 255, 255, .72);
            text-decoration: none;
            transition: .3s ease;
        }.sc-tw .links a:hover{
            background: rgba(255, 255, 255, .09);
            color: white;
        }.sc-tw .footer-bottom{
            margin-top: 34px;
            padding-top: 22px;
            border-top: 1px solid rgba(255, 255, 255, .08);
            display: flex;
            justify-content: space-between;
            gap: 20px;
            flex-wrap: wrap;
            color: rgba(255, 255, 255, .52);
            font-size: 12px;
            text-transform: uppercase;
            letter-spacing: .22em;
        }.sc-tw .reveal{
            opacity: 0;
            transform: translateY(30px);
            transition: opacity .8s ease, transform .8s cubic-bezier(.16, 1, .3, 1);
        }.sc-tw .reveal.in{
            opacity: 1;
            transform: translateY(0);
        }

        @keyframes sheen {to{
                transform: translateX(240%) rotate(10deg);
            }
        }

        @keyframes breath {0%,100%{
                transform: scale(1);
            }50%{
                transform: scale(1.012);
            }
        }

        @keyframes blink {50%{
                opacity: 0;
            }
        }.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
            animation-duration: .75s;
            animation-timing-function: cubic-bezier(.16, 1, .3, 1);
        }

        @media (max-width: 1180px) {.sc-tw .section-heading,.sc-tw .footer-grid{
                grid-template-columns: 1fr;
            }.sc-tw .projects-grid{
                grid-template-columns: repeat(6, 1fr);
            }.sc-tw .project,.sc-tw .project.wide{
                grid-column: span 6;
            }.sc-tw .code-body{
                grid-template-columns: 1fr;
            }.sc-tw .footer-grid p{
                max-width: none;
            }
        }

        @media (max-width: 760px) {.sc-tw .wrap,.sc-tw .footer-shell{
                width: min(100% - 20px, 1600px);
            }.sc-tw .hero-shell{
                padding: 18px 14px 20px;
            }.sc-tw .hero-title{
                font-size: clamp(3.4rem, 14vw, 6.8rem);
            }.sc-tw .hero-sub{
                font-size: 15px;
            }.sc-tw .section{
                padding: 92px 0;
            }.sc-tw .projects{
                padding: 92px 0;
            }.sc-tw .footer{
                padding: 92px 0 72px;
            }.sc-tw .projects-grid{
                grid-template-columns: 1fr;
            }.sc-tw .project,.sc-tw .project.wide{
                grid-column: span 1;
            }.sc-tw .footer-bottom{
                gap: 10px;
